(deps, func(pkgID string, dependsOn []string) ftypes.Dependency {\n\t\tif _, ok := pkgs[pkgID]; !ok {\n\t\t\treturn ftypes.Dependency{}\n\t\t}\n\n\t\t// Filter out dependencies that are not in the package list\n\t\tvar dependsOnIDs []string\n\t\tfor _, depID := range dependsOn {\n\t\t\tif _, ok := pkgs[depID]; ok {\n\t\t\t\tdependsOnIDs = append(dependsOnIDs, depID)\n\t\t\t}\n\t\t}\n\n\t\treturn ftypes.Dependency{\n\t\t\tID:        pkgID,\n\t\t\tDependsOn: dependsOnIDs,\n\t\t}\n\t})\n\n\tpkgSlice := lo.Values(pkgs)\n\tsort.Sort(ftypes.Packages(pkgSlice))\n\tsort.Sort(ftypes.Dependencies(depSlice))\n\n\treturn pkgSlice, depSlice, nil\n}\n\nfunc packageID(name, ver string) string {\n\treturn dependency.ID(ftypes.PyLock, name, ver)\n}\n", "numLines": 99, "startLine": 1, "totalLines": 99}}

1	package pyproject
2	
3	import (
4		"io"
5		"strings"
6	
7		"github.com/BurntSushi/toml"
8		"github.com/samber/lo"
9		"golang.org/x/xerrors"
10	
11		"github.com/aquasecurity/trivy/pkg/dependency/parser/python"
12		"github.com/aquasecurity/trivy/pkg/set"
13	)
14	
15	type PyProject struct {
16		Tool    Tool    `toml:"tool"`
17		Project Project `toml:"project"`
18	}
19	
20	type Project struct {
21		Dependencies Dependencies `toml:"dependencies"`
22	}
23	
24	type Tool struct {
25		Poetry Poetry `toml:"poetry"`
26	}
27	
28	type Poetry struct {
29		Dependencies Dependencies     `toml:"dependencies"`
30		Groups       map[string]Group `toml:"group"`
31	}
32	
33	type Group struct {
34		Dependencies Dependencies `toml:"dependencies"`
35	}
36	
37	type Dependencies struct {
38		set.Set[string]
39	}
40	
41	// MainDeps returns set of main deps
42	// `poetry` only uses 1 list of main dependencies
43	// `project.dependencies` (first priority) or `tool.poetry.dependencies` (if `project.dependencies` is missing)
44	func (p PyProject) MainDeps() set.Set[string] {
45		deps := set.New[string]()
46		if p.Project.Dependencies.Set != nil {
47			deps.Append(p.Project.Dependencies.Items()...)
48		} else if p.Tool.Poetry.Dependencies.Set != nil {
49			deps.Append(p.Tool.Poetry.Dependencies.Items()...)
50		}
51		return deps
52	}
53	
54	func (d *Dependencies) UnmarshalTOML(data any) error {
55		switch deps := data.(type) {
56		case map[string]any: // For Poetry v1
57			d.Set = set.New[string](lo.MapToSlice(deps, func(pkgName string, _ any) string {
58				return python.NormalizePkgName(pkgName, true)
59			})...)
60		case []any: // For Poetry v2
61			d.Set = set.New[string]()
62			for i := range deps {
63				dep, ok := deps[i].(string)
64				if !ok {
65					return xerrors.Errorf("dependencies must be string, but got: %T", deps[i])
66				}
67				// There are some formats:
68				// e.g. `Flask == 1.1.4`, `Flask==1.1.4`, `Flask(>= 1.0.0)`, `pluggy[pre-commit,tox] (==0.13.1)`, etc.
69				dep = strings.NewReplacer(">", " ", "<", " ", "=", " ", "(", " ", "[", " ").Replace(dep)
70				d.Set.Append(strings.Fields(dep)[0]) // Save only name
71			}
72		default:
73			return xerrors.Errorf("dependencies must be map, but got: %T", data)
74		}
75	
76		return nil
77	}
78	
79	// Parser parses pyproject.toml defined in PEP518.
80	// https://peps.python.org/pep-0518/
81	type Parser struct {
82	}
83	
84	func NewParser() *Parser {
85		return &Parser{}
86	}
87	
88	func (p *Parser) Parse(r io.Reader) (PyProject, error) {
89		var conf PyProject
90		if _, err := toml.NewDecoder(r).Decode(&conf); err != nil {
91			return PyProject{}, xerrors.Errorf("toml decode error: %w", err)
92		}
93		return conf, nil
94	}
