1	package uv
2	
3	import (
4		"context"
5		"io"
6		"io/fs"
7		"os"
8		"path/filepath"
9	
10		"golang.org/x/xerrors"
11	
12		uvparser "github.com/aquasecurity/trivy/pkg/dependency/parser/python/uv"
13		"github.com/aquasecurity/trivy/pkg/fanal/analyzer"
14		"github.com/aquasecurity/trivy/pkg/fanal/analyzer/language"
15		"github.com/aquasecurity/trivy/pkg/fanal/types"
16		"github.com/aquasecurity/trivy/pkg/log"
17		"github.com/aquasecurity/trivy/pkg/utils/fsutils"
18	)
19	
20	func init() {
21		analyzer.RegisterPostAnalyzer(analyzer.TypeUv, NewUvAnalyzer)
22	}
23	
24	const version = 1
25	
26	type uvAnalyzer struct {
27		logger     *log.Logger
28		lockParser language.Parser
29	}
30	
31	func NewUvAnalyzer(_ analyzer.AnalyzerOptions) (analyzer.PostAnalyzer, error) {
32		return &uvAnalyzer{
33			logger:     log.WithPrefix("uv"),
34			lockParser: uvparser.NewParser(),
35		}, nil
36	}
37	
38	func (a *uvAnalyzer) PostAnalyze(ctx context.Context, input analyzer.PostAnalysisInput) (*analyzer.AnalysisResult, error) {
39		var apps []types.Application
40		required := func(_ string, _ fs.DirEntry) bool {
41			// Parse all required files: `uv.lock` (from a.Required func) + input.FilePatterns.Match()
42			return true
43		}
44	
45		err := fsutils.WalkDir(input.FS, ".", required, func(path string, _ fs.DirEntry, r io.Reader) error {
46			// Parse uv.lock
47			app, err := language.Parse(ctx, types.Uv, path, r, a.lockParser)
48			if err != nil {
49				a.logger.Warn("Failed to parse uv lockfile", log.Err(err))
50				return nil
51			} else if app == nil {
52				return nil
53			}
54	
55			apps = append(apps, *app)
56	
57			return nil
58		})
59		if err != nil {
60			return nil, xerrors.Errorf("walk error: %w", err)
61		}
62	
63		return &analyzer.AnalysisResult{
64			Applications: apps,
65		}, nil
66	}
67	
68	func (a *uvAnalyzer) Required(filePath string, _ os.FileInfo) bool {
69		return filepath.Base(filePath) == types.UvLock
70	}
71	
72	func (a *uvAnalyzer) Type() analyzer.Type {
73		return analyzer.TypeUv
74	}
75	
76	func (a *uvAnalyzer) Version() int {
77		return version
78	}
