132	
133		packages := lock.packages()
134		directDeps := rootPackage.directDeps()
135	
136		// Since each lockfile contains a root package with a list of direct dependencies,
137		// we can identify all production dependencies by traversing the dependency graph
138		// and collecting all the dependencies that are reachable from the root.
139		prodDeps := prodDeps(rootPackage, packages)
140	
141		var (
