147			pkgID := packageID(pkg.Name, pkg.Version)
148			relationship := ftypes.RelationshipIndirect
149			if pkg.isRoot() {
150				relationship = ftypes.RelationshipRoot
151			} else if directDeps.Contains(pkg.Name) {
152				relationship = ftypes.RelationshipDirect
153			}
154	
155			pkgs = append(pkgs, ftypes.Package{
156				ID:           pkgID,
157				Name:         pkg.Name,
158				Version:      pkg.Version,
159				Relationship: relationship,
160				Dev:          !prodDeps.Contains(pkg.Name),
161			})
162	
163			dependsOn := make([]string, 0, len(pkg.Dependencies))
164	
165			for depName := range pkg.directDeps().Iter() {
166				depPkg, exists := packages[depName]
167				if !exists {
168					continue
169				}
170				dependsOn = append(dependsOn, packageID(depName, depPkg.Version))
171			}
172	
173			if len(dependsOn) > 0 {
174				sort.Strings(dependsOn)
175				deps = append(deps, ftypes.Dependency{
176					ID:        pkgID,
177					DependsOn: dependsOn,
