85	func (a pylockAnalyzer) matchLockFile(filePath string) bool {
86		base := filepath.Base(filePath)
87	
88		// Detect default lock file name.
89		if base == types.PyLockFile {
90			return true
91		}
92	
93		// Check PEP 751 compliant lock file name (^pylock\.([^.]+)\.toml$)
94		identifier, ok := strings.CutPrefix(base, "pylock.")
95		if !ok {
96			return false
97		}
98		identifier, ok = strings.CutSuffix(identifier, ".toml")
99		if !ok {
100			return false
101		}
102		return identifier != "" && !strings.Contains(identifier, ".")
103	}
