116		if errors.Is(err, fs.ErrNotExist) {
117			a.logger.Debug("pyproject.toml not found", log.FilePath(path))
118			return nil
119		} else if err != nil {
120			return xerrors.Errorf("unable to parse %s: %w", path, err)
121		}
122	
123		directDeps := p.MainDeps()
124	
125		// Major tools don't save dependencies for packages in pylock.toml file,
126		// But if we detect root package - we should add dependencies got from pyproject.toml to it.
127		rootPkgIndex := -1
128		var rootPkgDependsOn []string
129	
130		for i, pkg := range app.Packages {
131			if pkg.Relationship == types.RelationshipRoot {
132				rootPkgIndex = i
133				continue
134			}
135			app.Packages[i].Relationship = types.RelationshipIndirect
136			if directDeps.Contains(pkg.Name) {
137				app.Packages[i].Relationship = types.RelationshipDirect
138				rootPkgDependsOn = append(rootPkgDependsOn, pkg.ID)
139			}
140		}
141	
142		if rootPkgIndex != -1 {
143			app.Packages[rootPkgIndex].DependsOn = rootPkgDependsOn
144		}
